from fractions import Fraction

def verify(witness):
    d = witness["d"]
    r = witness["r"]
    if r != len(d):
        return False
    if not all(isinstance(x, int) and x >= 3 for x in d):
        return False
    for i in range(len(d) - 1):
        if not d[i] < d[i+1]:
            return False
    s = sum(Fraction(1, x - 1) for x in d)
    return s >= 1

def run():
    result = verify(WITNESS)
    if result:
        return ("PASS", 0)
    return ("FAIL", 1)
